// Generates src/Lidar/cjkRanges.ts: subset id -> unicode-range, parsed from the fontsource CSS.
import fs from 'node:fs';
const css = fs.readFileSync('node_modules/@fontsource/noto-sans-sc/900.css', 'utf8');
const out = {};
for (const m of css.matchAll(/noto-sans-sc-([a-z0-9-]+?)-900-normal\.woff2[^}]*?unicode-range:\s*([^;]+);/g)) out[m[1]] = m[2].trim();
fs.writeFileSync('src/Lidar/cjkRanges.ts',
  '// Generated by scripts/cjk-ranges.mjs from @fontsource/noto-sans-sc (OFL-1.1). Do not edit.\n' +
  'export const RANGES: Record<string, string> = ' + JSON.stringify(out, null, 0) + ';\n');
console.log(Object.keys(out).length, 'subsets');
